E = {"src/config.py": [["PRECISION_TARGET = 0.90       # operating threshold must reach this on validation\n", "PRECISION_TARGET = 0.90       # operating threshold must reach this on validation\n# \"conservative\" (v2): 95% lower confidence bound of validation precision must reach the target.\n# \"point\" (v1, original): observed validation precision must reach the target. Both are reported.\nTHRESHOLD_RULE = \"conservative\"\n"]], "src/models.py": [["def choose_threshold(y_val, p_val, target=config.PRECISION_TARGET):\n    \"\"\"Lowest threshold (i.e. highest recall) whose validation precision reaches the target.\n\n    If no threshold reaches the target, fall back to the F1-maximising threshold and say so.\n    \"\"\"\n    prec, rec, thr = precision_recall_curve(y_val, p_val)\n    prec, rec = prec[:-1], rec[:-1]            # align with thr\n    ok = np.where(prec >= target)[0]\n    if len(ok):\n        i = ok[np.argmax(rec[ok])]\n        return float(thr[i]), True\n    f1 = 2 * prec * rec / np.clip(prec + rec, 1e-12, None)\n    return float(thr[np.argmax(f1)]), False\n\n\n", "def wilson_lower(p, n, z=1.645):\n    \"\"\"One-sided 95% lower confidence bound for a proportion p observed on n trials.\"\"\"\n    n = np.maximum(n, 1)\n    centre = p + z * z / (2 * n)\n    margin = z * np.sqrt(p * (1 - p) / n + z * z / (4 * n * n))\n    return (centre - margin) / (1 + z * z / n)\n\n\ndef choose_threshold(y_val, p_val, target=config.PRECISION_TARGET, rule=None):\n    \"\"\"Lowest threshold (i.e. highest recall) whose validation precision reaches the target.\n\n    rule \"point\"       : observed validation precision >= target (original rule, v1).\n    rule \"conservative\": 95% Wilson lower bound of validation precision >= target (v2).\n                         Protects against a small validation window giving a lucky estimate.\n    If no threshold reaches the target, fall back to the F1-maximising threshold and say so.\n    \"\"\"\n    rule = rule or config.THRESHOLD_RULE\n    prec, rec, thr = precision_recall_curve(y_val, p_val)\n    prec, rec = prec[:-1], rec[:-1]            # align with thr\n    if rule == \"conservative\":\n        tp = rec * int(np.sum(y_val))\n        flagged = np.where(prec > 0, tp / np.maximum(prec, 1e-12), 0)\n        crit = wilson_lower(prec, flagged)\n    else:\n        crit = prec\n    ok = np.where(crit >= target)[0]\n    if len(ok):\n        i = ok[np.argmax(rec[ok])]\n        return float(thr[i]), True\n    if rule == \"conservative\":\n        # target not provable: take the threshold with the highest confident precision (stay cautious)\n        return float(thr[np.argmax(crit)]), False\n    f1 = 2 * prec * rec / np.clip(prec + rec, 1e-12, None)\n    return float(thr[np.argmax(f1)]), False\n\n\n"]], "run_pipeline.py": [["            thr, met = choose_threshold(val[\"label\"].values, p_val)\n            v = evaluate(val[\"label\"].values, p_val, thr)\n            te = evaluate(test[\"label\"].values, p_test, thr)\n            rows.append({\"model\": m_name, \"feature_set\": set_name, \"n_features\": len(cols),\n                         \"threshold\": thr, \"precision_target_met_on_val\": met,\n                         **{f\"val_{k}\": x for k, x in v.items()},\n                         **{f\"test_{k}\": x for k, x in te.items()},\n                         \"fit_seconds\": round(time.time() - t0, 1)})\n            fitted[(m_name, set_name)] = (model, p_val, p_test, thr)\n            log(f\"  {m_name:28s} {set_name:22s} test P={te['precision']:.3f} R={te['recall']:.3f} \"\n                f\"F1={te['f1']:.3f} PR-AUC={te['pr_auc']:.3f}\")\n", "            thr, met = choose_threshold(val[\"label\"].values, p_val)\n            v = evaluate(val[\"label\"].values, p_val, thr)\n            te = evaluate(test[\"label\"].values, p_test, thr)\n            # original v1 rule, kept for transparent reporting\n            thr1, _ = choose_threshold(val[\"label\"].values, p_val, rule=\"point\")\n            te1 = evaluate(test[\"label\"].values, p_test, thr1)\n            rows.append({\"model\": m_name, \"feature_set\": set_name, \"n_features\": len(cols),\n                         \"threshold\": thr, \"threshold_rule\": config.THRESHOLD_RULE,\n                         \"precision_target_met_on_val\": met,\n                         **{f\"val_{k}\": x for k, x in v.items()},\n                         **{f\"test_{k}\": x for k, x in te.items()},\n                         \"v1_threshold\": thr1, \"v1_test_precision\": te1[\"precision\"],\n                         \"v1_test_recall\": te1[\"recall\"], \"v1_test_f1\": te1[\"f1\"],\n                         \"fit_seconds\": round(time.time() - t0, 1)})\n            fitted[(m_name, set_name)] = (model, p_val, p_test, thr)\n            log(f\"  {m_name:28s} {set_name:22s} thr={thr:.3f} test P={te['precision']:.3f} R={te['recall']:.3f} \"\n                f\"F1={te['f1']:.3f} PR-AUC={te['pr_auc']:.3f} | v1 thr={thr1:.3f} P={te1['precision']:.3f} R={te1['recall']:.3f}\")\n"], ["        f\"- Precision target met on validation: {bool(best['precision_target_met_on_val'])}\", \"\",\n", "        f\"- Precision target met on validation: {bool(best['precision_target_met_on_val'])}\",\n        f\"- Threshold rule: {best['threshold_rule']} (threshold {best['threshold']:.3f}). \"\n        f\"Original point-estimate rule (v1): threshold {best['v1_threshold']:.3f}, test precision \"\n        f\"{best['v1_test_precision']:.3f}, recall {best['v1_test_recall']:.3f}.\", \"\",\n"]]}
ok = True
for f, pairs in E.items():
    s = open(f).read()
    for old, new in pairs:
        if new in s: continue
        if old not in s:
            print("NOT FOUND in", f); ok = False; continue
        s = s.replace(old, new)
